mapper.select:
SELECT a.announcement_id, a.title, a.field_code, c.code_name AS field_name, a.total_budget, a.max_grant, a.start_date, a.end_date, a.content, a.status, a.view_count, a.writer_id, u.user_name AS writer_name, a.created_at FROM announcement a LEFT JOIN com_code_detail c ON a.field_code = c.code_id AND c.group_id = 'FIELD' LEFT JOIN users u ON a.writer_id = u.user_id
AND a.field_code = #{fieldCode}
AND a.status = #{status}
AND (a.title LIKE CONCAT('%', #{keyword}, '%') OR a.content LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY a.announcement_id DESC

mapper.insert:
INSERT INTO announcement (
    title, field_code, total_budget, max_grant, start_date, end_date, content, status, view_count, writer_id
) VALUES (
    #{title}, #{fieldCode}, #{totalBudget}, #{maxGrant}, #{startDate}, #{endDate}, #{content}, #{status}, 0, #{writerId}
)

mapper.update:
UPDATE announcement
SET view_count = view_count + 1
WHERE announcement_id = #{announcementId}
